CAP = 100


def agirlik(b):
    return sum(w for w, x in zip(W, b) if x)


def deger(b):
    return sum(v for v, x in zip(V, b) if x)


def onar(b):
    """Kapasite asiliyorsa deger/agirlik orani en kotu nesneyi cikar."""
    b = list(b)
    atilan = []
    while agirlik(b) > CAP:
        icerdekiler = [i for i in range(len(b)) if b[i]]
        en_kotu = min(icerdekiler, key=lambda i: V[i] / W[i])
        b[en_kotu] = 0
        atilan.append(en_kotu + 1)
    return b, atilan


