def tek_nokta(p1, p2, k):
    return p1[:k] + p2[k:]


def pmx(p1, p2, i, j):
    cocuk = [None] * n
    cocuk[i:j] = p1[i:j]
    for yer in range(i, j):
        gen = p2[yer]
        if gen in cocuk[i:j]:
            continue
        hedef = yer
        while True:
            karsi = p1[hedef]
            hedef = p2.index(karsi)
            if not (i <= hedef < j):
                break
        cocuk[hedef] = gen
    for yer in range(n):
        if cocuk[yer] is None:
            cocuk[yer] = p2[yer]
    return cocuk


def ox(p1, p2, i, j):
    cocuk = [None] * n
    cocuk[i:j] = p1[i:j]
    kalan = [g for g in p2[j:] + p2[:j] if g not in p1[i:j]]
    yerler = list(range(j, n)) + list(range(0, i))
    for yer, gen in zip(yerler, kalan):
        cocuk[yer] = gen
    return cocuk


def cx(p1, p2):
    cocuk = [None] * n
    yer = 0
    while cocuk[yer] is None:
        cocuk[yer] = p1[yer]
        yer = p1.index(p2[yer])
    for t in range(n):
        if cocuk[t] is None:
            cocuk[t] = p2[t]
    return cocuk


