import math
from itertools import combinations

L = 8


class LCG:
    def __init__(self, seed):
        self.s = seed

    def nxt(self):
        self.s = (1103515245 * self.s + 12345) % (2 ** 31)
        return self.s

    def u(self):
        return self.nxt() / 2 ** 31


def ort_hamming(pop):
    ciftler = list(combinations(pop, 2))
    return sum(sum(1 for a, b in zip(x, y) if a != b) for x, y in ciftler) / len(ciftler)


def entropi(pop):
    toplam = 0.0
    for j in range(L):
        p = sum(1 for s in pop if s[j] == "1") / len(pop)
        for q in (p, 1 - p):
            if q > 0:
                toplam -= q * math.log2(q)
    return toplam / L


