ISLEM = ["+", "-", "*"]
TERMINAL = ["x", "1", "2"]
# hedef fonksiyon: x^2 - x
HEDEF = [(x, x * x - x) for x in (-2.0, -1.0, 0.0, 1.0, 2.0, 3.0)]


def tam_agac(rng, derinlik):
    """'full' yontemi: butun yapraklar ayni derinlikte."""
    if derinlik == 0:
        return TERMINAL[rng.nxt() % len(TERMINAL)]
    op = ISLEM[rng.nxt() % len(ISLEM)]
    return (op, tam_agac(rng, derinlik - 1), tam_agac(rng, derinlik - 1))


def boyut(t):
    return 1 if isinstance(t, str) else 1 + boyut(t[1]) + boyut(t[2])


def derinlik(t):
    return 0 if isinstance(t, str) else 1 + max(derinlik(t[1]), derinlik(t[2]))


def hesapla(t, x):
    if isinstance(t, str):
        return x if t == "x" else float(t)
    a, b = hesapla(t[1], x), hesapla(t[2], x)
    return a + b if t[0] == "+" else (a - b if t[0] == "-" else a * b)


def hata(t):
    return sum(abs(hesapla(t, x) - y) for x, y in HEDEF)


def yollar(t, yol=()):
    out = [yol]
    if not isinstance(t, str):
        out += yollar(t[1], yol + (1,))
        out += yollar(t[2], yol + (2,))
    return out


def al(t, yol):
    return t if not yol else al(t[yol[0]], yol[1:])


def koy(t, yol, yeni):
    if not yol:
        return yeni
    if yol[0] == 1:
        return (t[0], koy(t[1], yol[1:], yeni), t[2])
    return (t[0], t[1], koy(t[2], yol[1:], yeni))


def yazdir(t):
    return t if isinstance(t, str) else "(%s %s %s)" % (t[0], yazdir(t[1]), yazdir(t[2]))


