W = [25, 20, 40, 15, 45, 30, 10, 35, 12, 38, 24, 18, 47, 9, 31, 27]
H = [18, 25, 30, 12, 35, 22, 8, 28, 15, 33, 19, 14, 40, 7, 26, 21]
CAP_W, CAP_H, L = 200, 150, 16
OPT = 288
BUTCE = 3000
LAM_W, LAM_H = 2.0, 2.5          # 3. hafta: max(v/w)=1.889, max(v/h)=2.429 ustu


class LCG:
    def __init__(self, seed):
        self.s = seed

    def nxt(self):
        self.s = (1103515245 * self.s + 12345) % (2 ** 31)
        return self.s

    def u(self):
        return self.nxt() / 2 ** 31


BELLEK = {}


def oz(s):
    """Onbellekli degerlendirme: ayni kromozom kosum boyunca cok kez uretilir."""
    if s in BELLEK:
        return BELLEK[s]
    d = w = h = 0
    for i, c in enumerate(s):
        if c == "1":
            d += V[i]
            w += W[i]
            h += H[i]
    BELLEK[s] = (d, w, h)
    return d, w, h


def uygunluk(s):
    d, w, h = oz(s)
    return d - LAM_W * max(0, w - CAP_W) - LAM_H * max(0, h - CAP_H)


def ham(s):
    """Uygun ise ham deger, degilse 0 (raporlanacak sonuc budur)."""
    d, w, h = oz(s)
    return d if (w <= CAP_W and h <= CAP_H) else 0


def rastgele(rng):
    return "".join("1" if rng.u() < 0.5 else "0" for _ in range(L))


def rastgele_arama(tohum):
    rng = LCG(tohum)
    en, adim = 0, None
    for t in range(1, BUTCE + 1):
        v = ham(rastgele(rng))
        if v > en:
            en = v
            if v == OPT and adim is None:
                adim = t
    return en, adim


def tepe_tirmanma(tohum):
    rng = LCG(tohum)
    x = rastgele(rng)
    f = uygunluk(x)
    en, adim = ham(x), (1 if ham(x) == OPT else None)
    for t in range(2, BUTCE + 1):
        i = rng.nxt() % L
        y = x[:i] + ("0" if x[i] == "1" else "1") + x[i + 1:]
        g = uygunluk(y)
        if g >= f:
            x, f = y, g
        if ham(x) > en:
            en = ham(x)
            if en == OPT and adim is None:
                adim = t
    return en, adim


def ga(tohum, N=40, k=3, pc=0.9, pm=1.0 / L, elit=1):
    rng = LCG(tohum)
    pop = [rastgele(rng) for _ in range(N)]
    harcanan = N
    en = max(ham(s) for s in pop)
    adim = harcanan if en == OPT else None
    while harcanan + N <= BUTCE:
        f = [uygunluk(s) for s in pop]

        def turnuva():
            b = None
            for _ in range(k):
                i = rng.nxt() % N
                if b is None or f[i] > f[b]:
                    b = i
            return pop[b]

        sirali = sorted(range(N), key=lambda i: -f[i])
        yeni = [pop[i] for i in sirali[:elit]]
        while len(yeni) < N:
            p1, p2 = turnuva(), turnuva()
            if rng.u() < pc:
                kes = 1 + rng.nxt() % (L - 1)
                c = p1[:kes] + p2[kes:]
            else:
                c = p1
            c = "".join(("1" if ch == "0" else "0") if rng.u() < pm else ch for ch in c)
            yeni.append(c)
        pop = yeni
        harcanan += N
        iyi = max(ham(s) for s in pop)
        if iyi > en:
            en = iyi
            if en == OPT and adim is None:
                adim = harcanan
    return en, adim


def ozet(ad, sonuclar):
    d = sorted(s[0] for s in sonuclar)
    k = len(d)
    medyan = (d[k // 2 - 1] + d[k // 2]) / 2 if k % 2 == 0 else d[k // 2]
    basari = [s for s in sonuclar if s[0] == OPT]
    if basari:
        pay = sum(s[1] for s in basari) + (k - len(basari)) * BUTCE
        ert = "%.1f" % (pay / len(basari))
    else:
        ert = "tanimsiz"
    print("%-16s medyan=%6.1f  Q1=%5.1f Q3=%5.1f  en iyi=%3d  basari=%2d/%d  ERT=%s"
          % (ad, medyan, d[k // 4], d[3 * k // 4], d[-1], len(basari), k, ert))


